// Fragen FIAE – Planen eines Softwareproduktes (FIAE-1 bis FIAE-8)
[
  // ---------------------------------------------------------------- FIAE-1 Projektmanagement in der Softwareentwicklung
  { id: "FIAE-1-01", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "1. Vorgehensmodelle", frage: "Wann eignet sich ein **klassisches** Vorgehen wie das Wasserfallmodell?", optionen: ["Wenn die Anforderungen klar und stabil sind", "Wenn sich Anforderungen ständig ändern", "Wenn der Kunde laufend eingebunden werden will", "Wenn es kein Budget gibt"], richtig: 0, erklaerung: "Änderungen sind im Wasserfall teuer." },
  { id: "FIAE-1-02", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "1. Vorgehensmodelle", frage: "Welches Merkmal kennzeichnet **agiles** Projektmanagement?", optionen: ["Iterative Entwicklung mit laufender Anpassung", "Vollständige Planung aller Details vor dem Start", "Abnahme erst nach Abschluss aller Phasen", "Feste Anforderungen über die gesamte Laufzeit"], richtig: 0, erklaerung: "Änderungen sind Teil des Prozesses." },
  { id: "FIAE-1-03", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "Scrum", frage: "Wer priorisiert in Scrum das **Product Backlog**?", optionen: ["Product Owner", "Scrum Master", "Developers", "Stakeholder"], richtig: 0, erklaerung: "Der Scrum Master sorgt für die Einhaltung von Scrum und beseitigt Hindernisse." },
  { id: "FIAE-1-04", modul: "FIAE-1", typ: "multi", niveau: 2, abschnitt: "Scrum", frage: "Welche **Events** gehören zu Scrum?", optionen: ["Sprint Planning", "Daily Scrum", "Sprint Review", "Retrospektive", "Lastenheftabnahme"], richtig: [0, 1, 2, 3], erklaerung: "Plus der Sprint selbst als Container." },
  { id: "FIAE-1-05", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "3. Planung und Steuerung", frage: "Was ist ein **Meilenstein**?", optionen: ["Ereignis ohne Dauer, markiert einen Zwischenstand", "Projektphase mit einer Dauer von zwei Wochen", "Kleinstes planbares Arbeitspaket im PSP", "Pufferzeit am Ende des kritischen Pfades"], richtig: 0, erklaerung: "Z. B. „Pflichtenheft abgenommen“." },
  { id: "FIAE-1-06", modul: "FIAE-1", typ: "mc", niveau: 2, abschnitt: "3. Planung und Steuerung", frage: "Was ist **Change Request Management**?", optionen: ["Änderungen erfassen, bewerten, entscheiden, dokumentieren", "Änderungen sofort umsetzen, sobald der Kunde sie nennt", "Alle Änderungswünsche bis zum Projektende ablehnen", "Änderungen erst nach der Abnahme im Wartungsvertrag"], richtig: 0, erklaerung: "So bleiben Zeit, Kosten und Qualität unter Kontrolle." },
  { id: "FIAE-1-07", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "3. Planung und Steuerung", frage: "Was sind **Lessons Learned**?", optionen: ["Erfahrungen am Projektende für künftige Projekte", "Schulungen der Anwender vor dem Projektstart", "Liste der Anforderungen aus dem Lastenheft", "Protokolle der Abnahmetests beim Kunden"], richtig: 0, erklaerung: "Positive und negative Erfahrungen – Wissensmanagement." },
  { id: "FIAE-1-08", modul: "FIAE-1", typ: "mc", niveau: 2, abschnitt: "Stakeholderanalyse", frage: "Das Pflegepersonal befürchtet Überwachung durch die neue Software. Welche Maßnahme passt?", optionen: ["Datenschutzkonzept vorstellen, Betriebsrat einbinden", "Die Einführung verschieben, bis sich die Sorge legt", "Nur die Stationsleitungen über das Projekt informieren", "Die Protokollierung in der Software komplett abschalten"], richtig: 0, erklaerung: "Befürchtung und Maßnahme müssen zusammenpassen." },
  { id: "FIAE-1-09", modul: "FIAE-1", typ: "multi", niveau: 2, abschnitt: "Umfeld- und Machbarkeitsanalyse", frage: "Welche Aspekte gehören zur **Machbarkeitsprüfung**?", optionen: ["Marktanalyse", "Technische Machbarkeit", "Rechtliche Machbarkeit", "Wirtschaftliche Machbarkeit", "Detaillierte Klassenmodellierung"], richtig: [0, 1, 2, 3], erklaerung: "Außerdem Konkurrenz, Preis und Organisation." },
  { id: "FIAE-1-10", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "Risiken", frage: "Wie wird ein Projektrisiko bewertet?", optionen: ["Eintrittswahrscheinlichkeit × Schadensausmaß", "Budget ÷ geplante Projektdauer", "Anzahl der Stakeholder × Laufzeit", "Schadensausmaß ÷ Eintrittswahrscheinlichkeit"], richtig: 0, erklaerung: "Dazu gehört immer eine Gegenmaßnahme." },
  { id: "FIAE-1-11", modul: "FIAE-1", typ: "mc", niveau: 2, abschnitt: "Risiken", frage: "Risiko: Die Gastronomen ändern ihre Anforderungen während des Projekts. Welche Gegenmaßnahme passt?", optionen: ["Agiles Vorgehen mit regelmäßigen Reviews mit den Stakeholdern", "Anforderungen einfrieren und Änderungen ignorieren", "Das Projekt abbrechen", "Mehr Entwickler einstellen"], richtig: 0, erklaerung: "Früh erkennen und anpassen." },
  { id: "FIAE-1-12", modul: "FIAE-1", typ: "mc", niveau: 2, abschnitt: "Netzplan", frage: "Was ist der **Gesamtpuffer** eines Vorgangs?", optionen: ["Verschiebung ohne Auswirkung auf das Projektende", "Verschiebung ohne Auswirkung auf direkte Nachfolger", "Zeit vom Projektstart bis zum nächsten Meilenstein", "Differenz zwischen FAZ und FEZ desselben Vorgangs"], richtig: 0, erklaerung: "GP = SAZ − FAZ. Ohne Auswirkung auf Nachfolger = freier Puffer." },
  { id: "FIAE-1-13", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "Netzplan", frage: "Welche Vorgänge liegen auf dem **kritischen Pfad**?", optionen: ["Alle mit Gesamtpuffer 0", "Alle mit der längsten Dauer", "Alle mit freiem Puffer größer 0", "Die ersten drei Vorgänge"], richtig: 0, erklaerung: "Jede Verzögerung verschiebt das Projektende." },
  { id: "FIAE-1-14", modul: "FIAE-1", typ: "zahl", niveau: 2, abschnitt: "Netzplan", frage: "Vorgang C (Dauer 4) hat die Vorgänger A (FEZ 3) und B (FEZ 6). Wie groß ist der **FAZ** von C?", richtig: 6, toleranz: 0, erklaerung: "FAZ = größter FEZ der Vorgänger." },
  { id: "FIAE-1-15", modul: "FIAE-1", typ: "multi", niveau: 2, abschnitt: "4. Qualität und Abschluss", frage: "Welche Aufgaben gehören zur Vorbereitung des **Abschlussprotokolls**?", optionen: ["Soll-Ist-Vergleich mit dem Pflichtenheft", "Offene Punkte und Folgeaktivitäten festhalten", "Abnahme durch den Auftraggeber", "Neue Anforderungen umsetzen", "Lessons Learned sammeln"], richtig: [0, 1, 2, 4], erklaerung: "Neue Anforderungen gehören in ein Folgeprojekt." },
  { id: "FIAE-1-16", modul: "FIAE-1", typ: "mc", niveau: 2, abschnitt: "4. Qualität und Abschluss", frage: "Wie lässt sich der **Projekterfolg nach Projektende** prüfen?", optionen: ["Anhand vorher festgelegter Kennzahlen", "Allein anhand der eingehaltenen Projektkosten", "Anhand der Anzahl umgesetzter Anforderungen", "Durch die Zufriedenheit des Projektteams"], richtig: 0, erklaerung: "Z. B. Bearbeitungszeit, Fehlerquote, Zufriedenheit, Amortisation." },
  { id: "FIAE-1-17", modul: "FIAE-1", typ: "multi", niveau: 2, abschnitt: "4. Qualität und Abschluss", frage: "Welche Maßnahmen sichern die **Qualität in der Softwareentwicklung**?", optionen: ["Code-Reviews", "Definierte Testumgebungen und Testdaten", "CI/CD mit automatischen Tests", "Verzicht auf Versionsverwaltung", "Coding-Guidelines"], richtig: [0, 1, 2, 4], erklaerung: "Versionsverwaltung ist ein wichtiges Werkzeug." },
  { id: "FIAE-1-18", modul: "FIAE-1", typ: "multi", niveau: 2, abschnitt: "Entscheidungen im Projekt", frage: "Welche **Vorteile** hat es, die Entwicklung an einen Dienstleister auszulagern?", optionen: ["Bessere Kostenkontrolle durch Festpreis", "Wenig Bindung eigener Ressourcen", "Wettbewerb senkt den Preis", "Kein Know-how-Verlust", "Keine Abhängigkeit"], richtig: [0, 1, 2], erklaerung: "Know-how-Verlust und Abhängigkeit sind gerade Nachteile." },
  { id: "FIAE-1-19", modul: "FIAE-1", typ: "mc", niveau: 1, abschnitt: "3. Planung und Steuerung", frage: "Welche Größen bilden das **magische Dreieck** des Projektmanagements?", optionen: ["Leistung/Qualität, Zeit, Kosten", "Team, Kunde, Budget", "Analyse, Entwurf, Test", "Risiko, Chance, Nutzen"], richtig: 0, erklaerung: "Ändert sich eine Größe, sind die anderen betroffen." },

  // ---------------------------------------------------------------- FIAE-2 Anforderungen und Use Cases
  { id: "FIAE-2-01", modul: "FIAE-2", typ: "mc", niveau: 1, abschnitt: "1. Anforderungsdokumente", frage: "Wer erstellt das **Pflichtenheft**?", optionen: ["Der Auftragnehmer", "Der Auftraggeber", "Die IHK", "Der Endanwender"], richtig: 0, erklaerung: "Pflichtenheft = wie und womit; Lastenheft (Auftraggeber) = was und wofür." },
  { id: "FIAE-2-02", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "Funktional und nichtfunktional", frage: "Welche Anforderung ist **nichtfunktional**?", optionen: ["Die App antwortet bei 500 Nutzern in unter 2 Sekunden", "Benutzer können einen Termin buchen", "Die App sendet eine Push-Nachricht bei Fehlern", "Eingaben werden validiert"], richtig: 0, erklaerung: "Nichtfunktional = wie gut (Leistung, Verfügbarkeit, Usability …)." },
  { id: "FIAE-2-03", modul: "FIAE-2", typ: "multi", niveau: 2, abschnitt: "Funktional und nichtfunktional", frage: "Welche Anforderungen sind **funktional**?", optionen: ["Authentifizierung der Benutzer", "Export der Daten als CSV", "Verfügbarkeit 99,5 %", "Schnittstelle zum ERP-System", "Bedienbarkeit für Ungeübte"], richtig: [0, 1, 3], erklaerung: "Verfügbarkeit und Bedienbarkeit sind Qualitätsanforderungen." },
  { id: "FIAE-2-04", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "2. Softwarequalität nach ISO/IEC 25010", frage: "Welches Qualitätsmerkmal beschreibt, dass ein System unter festgelegten Bedingungen über einen Zeitraum korrekt funktioniert?", optionen: ["Zuverlässigkeit", "Übertragbarkeit", "Kompatibilität", "Benutzbarkeit"], richtig: 0, erklaerung: "Mit Reife, Verfügbarkeit, Fehlertoleranz und Wiederherstellbarkeit." },
  { id: "FIAE-2-05", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "2. Softwarequalität nach ISO/IEC 25010", frage: "Ein gut strukturierter, modularer Code lässt sich leicht anpassen. Welches Merkmal ist gemeint?", optionen: ["Wartbarkeit (Änderbarkeit)", "Leistungseffizienz", "Sicherheit", "Funktionale Eignung"], richtig: 0, erklaerung: "Modularität, Analysierbarkeit, Änderbarkeit, Testbarkeit." },
  { id: "FIAE-2-06", modul: "FIAE-2", typ: "mc", niveau: 1, abschnitt: "3. Use-Case-Diagramm", frage: "Wo werden **Akteure** im Use-Case-Diagramm gezeichnet?", optionen: ["Außerhalb der Systemgrenze", "Innerhalb der Systemgrenze", "Als Ellipse neben den Anwendungsfällen", "Nur im Sequenzdiagramm, nicht im Use-Case"], richtig: 0, erklaerung: "Anwendungsfälle stehen innerhalb, Akteure außerhalb." },
  { id: "FIAE-2-07", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "„Bestellen“ führt **immer** „Anmelden“ aus. Welche Beziehung?", optionen: ["«include» von Bestellen zu Anmelden", "«extend» von Anmelden zu Bestellen", "Generalisierung", "Assoziation zu einem Akteur"], richtig: 0, erklaerung: "include = immer, Pfeil vom Basis- zum inkludierten Fall." },
  { id: "FIAE-2-08", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "„Gutschein einlösen“ ist beim Bezahlen **optional**. Welche Beziehung und Pfeilrichtung?", optionen: ["«extend» von Gutschein einlösen zu Bezahlen", "«include» von Bezahlen zu Gutschein einlösen", "«extend» von Bezahlen zu Gutschein einlösen", "Generalisierung"], richtig: 0, erklaerung: "Die Erweiterung zeigt auf den Basisfall." },
  { id: "FIAE-2-09", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "Ein Administrator darf alles, was ein Benutzer darf, und mehr. Wie modelliert man das?", optionen: ["Generalisierung: Administrator erbt von Benutzer", "«include» vom Administrator zum Benutzer", "«extend» vom Benutzer zum Administrator", "Assoziation zwischen beiden Akteuren"], richtig: 0, erklaerung: "Pfeil mit leerem Dreieck vom Administrator zum Benutzer." },
  { id: "FIAE-2-10", modul: "FIAE-2", typ: "mc", niveau: 1, abschnitt: "User Stories", frage: "Wie ist eine **User Story** aufgebaut?", optionen: ["Als ‹Rolle› möchte ich ‹Funktion›, damit ‹Nutzen›", "Wenn ‹Bedingung›, dann ‹Aktion›, sonst ‹Alternative›", "‹Akteur› führt ‹Anwendungsfall› im ‹System› aus", "Gegeben ‹Kontext›, wenn ‹Aktion›, dann ‹Ergebnis›"], richtig: 0, erklaerung: "Given–When–Then beschreibt die Akzeptanzkriterien." },
  { id: "FIAE-2-11", modul: "FIAE-2", typ: "multi", niveau: 2, abschnitt: "1. Anforderungsdokumente", frage: "Welche Eigenschaften haben **gute Anforderungen**?", optionen: ["Eindeutig", "Prüfbar (messbar)", "Vollständig und konsistent", "Möglichst allgemein formuliert", "Priorisiert"], richtig: [0, 1, 2, 4], erklaerung: "„Schnell“ oder „benutzerfreundlich“ ohne Maß ist nicht prüfbar." },
  { id: "FIAE-2-12", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "4. Beispiel eRechnung", frage: "Was ist das **Hauptziel** einer E-Rechnung?", optionen: ["Maschinelle Verarbeitung der Rechnungsdaten", "Einheitliche PDF-Darstellung aller Rechnungen", "Rechtssicherer Versand ausschließlich per E-Mail", "Verzicht auf Aufbewahrung der Rechnungen"], richtig: 0, erklaerung: "Ein strukturierter Datensatz (XRechnung, ZUGFeRD) – eine reine PDF ist keine E-Rechnung." },
  { id: "FIAE-2-13", modul: "FIAE-2", typ: "mc", niveau: 3, abschnitt: "4. Beispiel eRechnung", frage: "Eine XML-Rechnung besteht die **XSD-Schemavalidierung**, aber der Nettobetrag wurde aus Bruttowerten gebildet. Warum fiel das nicht auf?", optionen: ["XSD prüft nur Struktur und Typen, keine Rechenlogik", "XSD prüft nur die Wohlgeformtheit des XML", "Beträge werden von XSD grundsätzlich ignoriert", "Die Prüfung erfolgt erst beim Empfänger"], richtig: 0, erklaerung: "Für Logik braucht es zusätzliche Tests (z. B. Unit-Tests)." },
  { id: "FIAE-2-14", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "Anwendungsfallbeschreibung", frage: "Was gehört **nicht** in eine Anwendungsfallbeschreibung?", optionen: ["Der Quellcode der Implementierung", "Akteur und Vorbedingung", "Standardablauf in Schritten", "Alternative Abläufe und Nachbedingung"], richtig: 0, erklaerung: "Die Beschreibung bleibt fachlich." },
  { id: "FIAE-2-15", modul: "FIAE-2", typ: "text", niveau: 1, abschnitt: "2. Softwarequalität nach ISO/IEC 25010", frage: "Welche ISO/IEC-Norm beschreibt das Qualitätsmodell für Software (Nummer)?", richtig: ["25010", "ISO/IEC 25010", "ISO 25010"], erklaerung: "Nachfolger der ISO 9126." },
  { id: "FIAE-2-16", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "Wie werden Anwendungsfälle sinnvoll benannt?", optionen: ["Verb + Objekt aus Nutzersicht („Tisch reservieren“)", "Als Oberflächenschritt („Button klicken“)", "Mit dem Namen der umsetzenden Klasse", "Als Substantiv („Reservierungsverwaltung“)"], richtig: 0, erklaerung: "Ein Anwendungsfall liefert einem Akteur einen Nutzen." },

  // ---------------------------------------------------------------- FIAE-3 UML Aktivität, Sequenz und Zustand
  { id: "FIAE-3-01", modul: "FIAE-3", typ: "mc", niveau: 1, abschnitt: "1. Aktivitätsdiagramm", frage: "Womit werden im Aktivitätsdiagramm **parallele** Abläufe begonnen und wieder zusammengeführt?", optionen: ["Gabelung (Fork) und Vereinigung (Join)", "Verzweigung und Zusammenführung (Raute)", "Startknoten und Ablaufende", "Aktivitätsbereiche (Swimlanes)"], richtig: 0, erklaerung: "Der Join wartet, bis alle Zweige fertig sind (Synchronisation)." },
  { id: "FIAE-3-02", modul: "FIAE-3", typ: "mc", niveau: 1, abschnitt: "1. Aktivitätsdiagramm", frage: "Wie werden Bedingungen an einer Verzweigung notiert?", optionen: ["In eckigen Klammern, z. B. [Wert > 38]", "In runden Klammern, z. B. (Wert > 38)", "In geschweiften Klammern, z. B. {Wert > 38}", "Als Notiz mit umgeknickter Ecke"], richtig: 0, erklaerung: "Die Bedingungen müssen vollständig und sich ausschließend sein." },
  { id: "FIAE-3-03", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "1. Aktivitätsdiagramm", frage: "Was ist der Unterschied zwischen **Endknoten** und **Ablaufende**?", optionen: ["Endknoten beendet alles, Ablaufende nur einen Zweig", "Ablaufende beendet alles, Endknoten nur einen Zweig", "Beide beenden nur den jeweiligen Zweig", "Endknoten startet einen neuen Durchlauf"], richtig: 0, erklaerung: "◉ = Ende gesamt, ⊗ = Ende eines Flusses." },
  { id: "FIAE-3-04", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "1. Aktivitätsdiagramm", frage: "Wozu dienen **Schwimmbahnen** (Partitionen)?", optionen: ["Sie zeigen, wer eine Aktion ausführt", "Sie zeigen parallele Abläufe", "Sie kennzeichnen Schleifen", "Sie ersetzen den Startknoten"], richtig: 0, erklaerung: "Z. B. Arzt, Pflege, System." },
  { id: "FIAE-3-05", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Wie wird eine **Antwort** (Rückgabe) im Sequenzdiagramm dargestellt?", optionen: ["Als gestrichelter Pfeil zurück zum Aufrufer", "Als durchgezogener Pfeil mit gefüllter Spitze", "Als Raute", "Als Balken"], richtig: 0, erklaerung: "Synchron = gefüllte Spitze, asynchron = offene Spitze, Antwort = gestrichelt." },
  { id: "FIAE-3-06", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Ein Codeabschnitt `if (…) { … }` **ohne else** wird im Sequenzdiagramm als welches Fragment dargestellt?", optionen: ["opt", "alt", "loop", "par"], richtig: 0, erklaerung: "alt entspricht if/else mit mehreren Alternativen." },
  { id: "FIAE-3-07", modul: "FIAE-3", typ: "mc", niveau: 1, abschnitt: "2. Sequenzdiagramm", frage: "Welches Fragment stellt eine **Wiederholung** dar?", optionen: ["loop", "opt", "alt", "ref"], richtig: 0, erklaerung: "loop [für jeden Patienten]." },
  { id: "FIAE-3-08", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Was bedeutet eine **synchrone** Nachricht?", optionen: ["Der Sender wartet auf die Antwort", "Der Sender arbeitet ohne Warten weiter", "Die Nachricht geht an alle Objekte", "Die Nachricht erzeugt ein neues Objekt"], richtig: 0, erklaerung: "Typisch für normale Methodenaufrufe." },
  { id: "FIAE-3-09", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "3. Zustandsdiagramm", frage: "Wie wird ein Übergang im Zustandsdiagramm beschriftet?", optionen: ["Ereignis [Bedingung] / Aktion", "Klasse.Methode()", "Nur mit einer Nummer", "Mit dem Objektnamen"], richtig: 0, erklaerung: "Z. B. Fahrgäste [Auslastung > 80 %]." },
  { id: "FIAE-3-10", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "3. Zustandsdiagramm", frage: "Welche Situation modelliert man am besten mit einem **Zustandsdiagramm**?", optionen: ["Status eines Auftrags (neu, in Arbeit, erledigt)", "Nachrichtenaustausch zwischen drei Objekten", "Tabellenstruktur einer relationalen Datenbank", "Anwendungsfälle und Akteure eines Systems"], richtig: 0, erklaerung: "Objekte mit klar unterscheidbaren Zuständen und Übergängen." },
  { id: "FIAE-3-11", modul: "FIAE-3", typ: "multi", niveau: 2, abschnitt: "Ist-Prozess analysieren", frage: "Welche Schwachstellen eines Ist-Prozesses sprechen für eine **Digitalisierung**?", optionen: ["Manuelle Übertragung von Messwerten", "Medienbrüche (Papier → System)", "Informationen erreichen Beteiligte zu spät", "Ein vollständig automatisierter Ablauf", "Fehleranfällige Zuordnung von Befunden"], richtig: [0, 1, 2, 4], erklaerung: "Ein automatisierter Ablauf ist bereits digital." },
  { id: "FIAE-3-12", modul: "FIAE-3", typ: "mc", niveau: 1, abschnitt: "1. Aktivitätsdiagramm", frage: "Wie viele **Startknoten** hat ein Aktivitätsdiagramm üblicherweise?", optionen: ["Einen", "Keinen", "Einen je Zweig", "Beliebig viele ohne Bedeutung"], richtig: 0, erklaerung: "Ein Einstiegspunkt, gefüllter Kreis." },
  { id: "FIAE-3-13", modul: "FIAE-3", typ: "mc", niveau: 3, abschnitt: "1. Aktivitätsdiagramm", frage: "Zwei parallele Zweige werden mit einer **Raute** statt einem Join zusammengeführt. Was ist das Problem?", optionen: ["Die Raute wartet nicht – Ablauf läuft doppelt weiter", "Rauten sind im Aktivitätsdiagramm nicht zulässig", "Die Raute wartet auf beide Zweige, das ist korrekt", "Nur der zuerst ankommende Zweig wird verworfen"], richtig: 0, erklaerung: "Parallelität braucht einen Synchronisationsbalken." },
  { id: "FIAE-3-14", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Was zeigt ein **Aktivierungsbalken** auf einer Lebenslinie?", optionen: ["Das Objekt ist gerade aktiv und führt etwas aus", "Das Objekt wird an dieser Stelle zerstört", "Hier beginnt eine alternative Verzweigung", "Hier wird eine Schleife wiederholt"], richtig: 0, erklaerung: "Schmales Rechteck auf der gestrichelten Lebenslinie." },

  // ---------------------------------------------------------------- FIAE-4 Objektorientierter Entwurf und Entwurfsmuster
  { id: "FIAE-4-01", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "1. Klassendiagramm", frage: "Welches Zeichen steht im Klassendiagramm für **private**?", optionen: ["-", "+", "#", "~"], richtig: 0, erklaerung: "+ public, # protected, ~ package." },
  { id: "FIAE-4-02", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "1. Klassendiagramm", frage: "Was bedeutet die Multiplizität `1..*`?", optionen: ["Mindestens eins, beliebig viele", "Keins oder eins", "Genau eins", "Beliebig viele, auch keins"], richtig: 0, erklaerung: "* bzw. 0..* erlaubt auch keins." },
  { id: "FIAE-4-03", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "1. Klassendiagramm", frage: "Rechnung und Rechnungsposition: Positionen existieren nicht ohne Rechnung. Welche Beziehung?", optionen: ["Komposition (gefüllte Raute an der Rechnung)", "Aggregation (leere Raute an der Rechnung)", "Komposition (gefüllte Raute an der Position)", "Gerichtete Assoziation ohne Raute"], richtig: 0, erklaerung: "Existenzabhängigkeit = Komposition." },
  { id: "FIAE-4-04", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "1. Klassendiagramm", frage: "Warum ist die Beziehung Personalverwaltung – Fahrer eine **Aggregation** und keine Komposition?", optionen: ["Fahrer existieren auch ohne die Personalverwaltung", "Weil es in der Verwaltung mehrere Fahrer gibt", "Weil Fahrer eigene Attribute und Methoden haben", "Weil Fahrer von der Verwaltung erzeugt werden"], richtig: 0, erklaerung: "Die Teile sind nicht existenzabhängig." },
  { id: "FIAE-4-05", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "1. Klassendiagramm", frage: "Wie wird die **Implementierung eines Interfaces** dargestellt?", optionen: ["Gestrichelte Linie mit leerem Dreieck", "Durchgezogene Linie mit leerem Dreieck", "Durchgezogene Linie mit gefüllter Raute", "Gestrichelte Linie mit offener Pfeilspitze"], richtig: 0, erklaerung: "Vererbung = durchgezogen, Realisierung = gestrichelt." },
  { id: "FIAE-4-06", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "2. OOP-Prinzipien", frage: "Was bedeutet **Kapselung**?", optionen: ["Private Attribute, Zugriff nur über Methoden", "Unterklassen erben alle Attribute der Oberklasse", "Mehrere Methoden haben denselben Namen", "Objekte werden gemeinsam in Listen gespeichert"], richtig: 0, erklaerung: "Geheimnisprinzip." },
  { id: "FIAE-4-07", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "2. OOP-Prinzipien", frage: "Was beschreibt **Polymorphie** mit dynamischer Bindung?", optionen: ["Zur Laufzeit entscheidet der tatsächliche Objekttyp", "Beim Kompilieren entscheidet der Variablentyp", "Eine Klasse hat mehrere Konstruktoren", "Eine Methode ruft sich rekursiv selbst auf"], richtig: 0, erklaerung: "Überladen (mehrere Signaturen) ist etwas anderes." },
  { id: "FIAE-4-08", modul: "FIAE-4", typ: "multi", niveau: 2, abschnitt: "2. OOP-Prinzipien", frage: "Welche Aussagen zu **abstrakten Klassen** stimmen?", optionen: ["Von ihnen können keine Objekte erzeugt werden", "Sie können Attribute enthalten", "Sie können abstrakte und implementierte Methoden enthalten", "Eine Klasse kann beliebig viele abstrakte Klassen erben (Java/C#)"], richtig: [0, 1, 2], erklaerung: "In Java/C# gibt es nur Einfachvererbung; mehrere Interfaces sind möglich." },
  { id: "FIAE-4-09", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "3. Entwurfsmuster", frage: "Was sind **Entwurfsmuster**?", optionen: ["Bewährte Lösungsschablonen für Entwurfsprobleme", "Fertig kompilierte Bibliotheken für Standardaufgaben", "Vorgaben der UML für die Diagrammgestaltung", "Vorlagen für die Formatierung von Quellcode"], richtig: 0, erklaerung: "Sie schaffen auch ein gemeinsames Vokabular." },
  { id: "FIAE-4-10", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "3. Entwurfsmuster", frage: "Zu welcher Kategorie gehört das **Singleton**?", optionen: ["Erzeugungsmuster", "Strukturmuster", "Verhaltensmuster", "Architekturmuster"], richtig: 0, erklaerung: "Genau eine Instanz – privater Konstruktor, statisches getInstance()." },
  { id: "FIAE-4-11", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Mehrere Anzeigen sollen automatisch aktualisiert werden, wenn sich ein Messwert ändert. Welches Muster?", optionen: ["Observer", "Singleton", "Facade", "Adapter"], richtig: 0, erklaerung: "Das Subjekt benachrichtigt alle angemeldeten Beobachter per update()." },
  { id: "FIAE-4-12", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Was kennzeichnet die **Factory Method**?", optionen: ["Unterklassen entscheiden, welches Objekt entsteht", "Es darf von der Klasse nur eine Instanz geben", "Eine vereinfachte Schnittstelle vor einem Subsystem", "Algorithmen werden zur Laufzeit ausgetauscht"], richtig: 0, erklaerung: "Die erzeugten Klassen brauchen eine gemeinsame Oberklasse/Schnittstelle." },
  { id: "FIAE-4-13", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "3. Entwurfsmuster", frage: "Zu welcher Kategorie gehört das **Facade**-Muster?", optionen: ["Strukturmuster", "Erzeugungsmuster", "Verhaltensmuster", "Testmuster"], richtig: 0, erklaerung: "Einfache Schnittstelle vor einem komplexen Subsystem." },
  { id: "FIAE-4-14", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Welches Muster passt, wenn eine inkompatible Schnittstelle eines Altsystems angebunden werden soll?", optionen: ["Adapter", "Observer", "Singleton", "Strategy"], richtig: 0, erklaerung: "Der Adapter übersetzt zwischen erwarteter und vorhandener Schnittstelle." },
  { id: "FIAE-4-15", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Wofür steht das **C** in MVC?", optionen: ["Controller – verarbeitet Eingaben und steuert", "Class – enthält die fachlichen Klassen", "Container – verwaltet die Objekte", "Collection – speichert die Daten"], richtig: 0, erklaerung: "Model – View – Controller." },
  { id: "FIAE-4-16", modul: "FIAE-4", typ: "mc", niveau: 3, abschnitt: "2. OOP-Prinzipien", frage: "Warum lässt sich ein Container mit Oberklassen-Liste leicht um neue Aufgabenarten erweitern?", optionen: ["Neue Unterklassen werden polymorph aufgerufen", "Der Container kennt alle konkreten Klassen", "Listen dürfen beliebig viele Elemente haben", "Interfaces werden dafür nicht benötigt"], richtig: 0, erklaerung: "Offen für Erweiterung, geschlossen für Änderung." },
  { id: "FIAE-4-17", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "1. Klassendiagramm", frage: "In welche Richtung zeigt der **Vererbungspfeil**?", optionen: ["Von der Unterklasse zur Oberklasse", "Von der Oberklasse zur Unterklasse", "In beide Richtungen", "Er hat keine Richtung"], richtig: 0, erklaerung: "„ist ein“ – das leere Dreieck sitzt an der Oberklasse." },

  // ---------------------------------------------------------------- FIAE-5 Datenmodellierung und Normalisierung
  { id: "FIAE-5-01", modul: "FIAE-5", typ: "mc", niveau: 1, abschnitt: "1. ER-Modell", frage: "Wie wird im ER-Modell (Chen) ein **Beziehungstyp** dargestellt?", optionen: ["Als Raute", "Als Rechteck", "Als Oval", "Als Pfeil"], richtig: 0, erklaerung: "Rechteck = Entität, Oval = Attribut." },
  { id: "FIAE-5-02", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "ER-Modell in Tabellen überführen", frage: "Wo steht bei einer **1:n-Beziehung** der Fremdschlüssel?", optionen: ["In der Tabelle der n-Seite", "In der Tabelle der 1-Seite", "In einer Zwischentabelle", "In beiden Tabellen"], richtig: 0, erklaerung: "Jeder Patient verweist auf seine Station." },
  { id: "FIAE-5-03", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "ER-Modell in Tabellen überführen", frage: "Wo werden **Attribute einer n:m-Beziehung** (z. B. Datum der Behandlung) gespeichert?", optionen: ["In der Zwischentabelle", "In der Tabelle Patient", "In der Tabelle Arzt", "In beiden Tabellen redundant"], richtig: 0, erklaerung: "Sie gehören zur Beziehung, nicht zu einer Entität." },
  { id: "FIAE-5-04", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "ER-Modell in Tabellen überführen", frage: "Warum eignet sich ein **Name** schlecht als Primärschlüssel?", optionen: ["Er ist nicht eindeutig und kann sich ändern", "Er ist zu kurz", "Namen dürfen nicht gespeichert werden", "Er ist immer NULL"], richtig: 0, erklaerung: "Besser: künstliche ID." },
  { id: "FIAE-5-05", modul: "FIAE-5", typ: "mc", niveau: 1, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Was ist **Redundanz**?", optionen: ["Dieselbe Information wird mehrfach gespeichert", "Daten werden verschlüsselt", "Daten fehlen", "Eine Tabelle hat einen Primärschlüssel"], richtig: 0, erklaerung: "Führt zu Inkonsistenzen und Anomalien." },
  { id: "FIAE-5-06", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Ein Gericht wird umbenannt und muss in hunderten Bestellzeilen geändert werden. Welche Anomalie?", optionen: ["Änderungsanomalie", "Einfügeanomalie", "Löschanomalie", "Verletzung der referenziellen Integrität"], richtig: 0, erklaerung: "Vergisst man eine Zeile, sind die Daten widersprüchlich." },
  { id: "FIAE-5-07", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Mit dem letzten Besuch eines Gastes geht auch die einzige Information über ein Gericht verloren. Welche Anomalie?", optionen: ["Löschanomalie", "Änderungsanomalie", "Einfügeanomalie", "Transaktionsfehler"], richtig: 0, erklaerung: "Einmalige Informationen hängen an einem anderen Datensatz." },
  { id: "FIAE-5-08", modul: "FIAE-5", typ: "mc", niveau: 1, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Was verlangt die **1. Normalform**?", optionen: ["Alle Attributwerte sind atomar", "Keine transitiven Abhängigkeiten", "Volle Abhängigkeit vom Gesamtschlüssel", "Jede Tabelle hat genau zwei Spalten"], richtig: 0, erklaerung: "Z. B. Name in Vorname/Nachname teilen." },
  { id: "FIAE-5-09", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Eine Kundentabelle enthält PLZ und Ort; Ort hängt von der PLZ ab. Welche Normalform ist verletzt?", optionen: ["3. Normalform (transitive Abhängigkeit)", "2. Normalform (partielle Abhängigkeit)", "1. Normalform (nicht atomare Werte)", "Keine – die Tabelle ist normalisiert"], richtig: 0, erklaerung: "Ort hängt über PLZ vom Schlüssel ab." },
  { id: "FIAE-5-10", modul: "FIAE-5", typ: "multi", niveau: 2, abschnitt: "3. Datenqualität", frage: "Welche Probleme treten beim **Import alter Excel-Daten** typischerweise auf?", optionen: ["Uneinheitliche Datumsformate", "Namen statt IDs mit unterschiedlicher Schreibweise", "Freitext für gleiche Sachverhalte", "Fehlende Pflichtwerte", "Zu viele Primärschlüssel"], richtig: [0, 1, 2, 3], erklaerung: "Lösung: bereinigen, validieren, Auswahllisten." },
  { id: "FIAE-5-11", modul: "FIAE-5", typ: "multi", niveau: 2, abschnitt: "4. NoSQL und große Datenmengen", frage: "Welche Vorteile bieten **NoSQL-Datenbanken**?", optionen: ["Flexibles Schema", "Gute horizontale Skalierung", "Datenstruktur passt zu Objekten im Programm", "Immer vollständige ACID-Transaktionen", "Einheitliche Abfragesprache für alle Systeme"], richtig: [0, 1, 2], erklaerung: "ACID und einheitliche Sprache sind eher Stärken relationaler Systeme." },
  { id: "FIAE-5-12", modul: "FIAE-5", typ: "zahl", niveau: 2, abschnitt: "Speicherbedarf abschätzen", frage: "Ein unkomprimiertes Foto hat **4 000 × 3 000 Pixel** mit **24 Bit** Farbtiefe. Wie groß ist es in **MB** (dezimal, 10^6 Byte)?", richtig: 36, toleranz: 0.01, einheit: "MB", erklaerung: "4 000 × 3 000 × 3 Byte = 36 000 000 Byte = 36 MB." },
  { id: "FIAE-5-13", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "1. ER-Modell", frage: "Ärzte behandeln viele Patienten, Patienten werden von mehreren Ärzten behandelt. Welche Kardinalität?", optionen: ["n:m", "1:n", "1:1", "0:1"], richtig: 0, erklaerung: "Wird mit einer Zwischentabelle (Behandlung) aufgelöst." },
  { id: "FIAE-5-14", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Ein neuer Gast soll angelegt werden, hat aber noch keinen Besuch – die Besuchsfelder bleiben leer. Welche Anomalie?", optionen: ["Einfügeanomalie", "Löschanomalie", "Änderungsanomalie", "Verletzung der 1. Normalform"], richtig: 0, erklaerung: "Information lässt sich nur mit leeren Feldern einfügen." },

  // ---------------------------------------------------------------- FIAE-6 Benutzeroberflächen, Barrierefreiheit und Usability
  { id: "FIAE-6-01", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "1. Vom Skizzieren zum Prototyp", frage: "Was unterscheidet ein **Mockup** von einem Wireframe?", optionen: ["Mockup zeigt das Design, Wireframe die Struktur", "Mockup ist programmiert, Wireframe nur skizziert", "Wireframe zeigt Farben, Mockup nur die Struktur", "Mockup und Wireframe sind dasselbe Dokument"], richtig: 0, erklaerung: "Der klickbare Prototyp kommt danach." },
  { id: "FIAE-6-02", modul: "FIAE-6", typ: "multi", niveau: 2, abschnitt: "1. Vom Skizzieren zum Prototyp", frage: "Welche Vorteile hat die Erstellung von **Mockups**?", optionen: ["Frühes Feedback von Kunden und Nutzern", "Missverständnisse werden früh und billig erkannt", "Gemeinsame Diskussionsgrundlage", "Ersetzt alle Tests", "Macht die Programmierung überflüssig"], richtig: [0, 1, 2], erklaerung: "Mockups ersetzen weder Tests noch Entwicklung." },
  { id: "FIAE-6-03", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "Steuerelemente passend wählen", frage: "Welches Steuerelement eignet sich für die Auswahl der **Krankenkasse** aus einer festen Liste?", optionen: ["Auswahlliste (Dropdown)", "Freitextfeld", "Checkbox", "Schieberegler"], richtig: 0, erklaerung: "Verhindert Tippfehler und uneinheitliche Werte." },
  { id: "FIAE-6-04", modul: "FIAE-6", typ: "multi", niveau: 2, abschnitt: "Steuerelemente passend wählen", frage: "Was gehört zu einer guten **Eingabemaske**?", optionen: ["Beschriftung zu jedem Feld", "Schaltflächen Speichern und Abbrechen", "Validierung mit verständlichen Fehlermeldungen", "Pflichtfelder ohne Kennzeichnung", "Logische Tab-Reihenfolge"], richtig: [0, 1, 2, 4], erklaerung: "Pflichtfelder sollten markiert sein." },
  { id: "FIAE-6-05", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "2. Usability", frage: "Welcher Grundsatz der ISO 9241-110 verlangt, dass sich ein Dialog so verhält, wie der Nutzer es gewohnt ist?", optionen: ["Erwartungskonformität", "Steuerbarkeit", "Aufgabenangemessenheit", "Benutzerbindung"], richtig: 0, erklaerung: "Z. B. Logo oben links führt zur Startseite." },
  { id: "FIAE-6-06", modul: "FIAE-6", typ: "multi", niveau: 2, abschnitt: "Usability testen", frage: "Welche Methoden eignen sich, um **Usability zu testen**?", optionen: ["Beobachtung mit lautem Denken", "Eye-Tracking", "Auswertung von Logdaten", "A/B-Tests", "Kompilieren des Codes"], richtig: [0, 1, 2, 3], erklaerung: "Kompilieren prüft nur die Syntax." },
  { id: "FIAE-6-07", modul: "FIAE-6", typ: "multi", niveau: 1, abschnitt: "3. Barrierefreiheit", frage: "Welche vier Prinzipien nennt die **WCAG**?", optionen: ["Wahrnehmbar", "Bedienbar", "Verständlich", "Robust", "Farbig"], richtig: [0, 1, 2, 3], erklaerung: "POUR: perceivable, operable, understandable, robust." },
  { id: "FIAE-6-08", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Welche Maßnahme macht Bilder für **blinde Nutzer** zugänglich?", optionen: ["Alternativtexte, die ein Screenreader vorliest", "Bilder in höherer Auflösung bereitstellen", "Bilder mit stärkerem Farbkontrast versehen", "Bilder als animierte Grafiken einbinden"], richtig: 0, erklaerung: "Außerdem sinnvolle Struktur mit Überschriften und Labels." },
  { id: "FIAE-6-09", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Seit wann gilt das **Barrierefreiheitsstärkungsgesetz (BFSG)** für viele Produkte und Dienstleistungen?", optionen: ["28.06.2025", "01.01.2020", "25.05.2018", "01.01.2030"], richtig: 0, erklaerung: "Z. B. für Onlineshops und Banking-Apps." },
  { id: "FIAE-6-10", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Ein Formular zeigt Fehler **nur durch rote Rahmenfarbe**. Was ist das Problem?", optionen: ["Farbe allein reicht nicht – Farbenblinde sehen es nicht", "Rote Rahmen sind nach WCAG grundsätzlich verboten", "Fehler dürfen erst nach dem Absenden erscheinen", "Kein Problem, Rot ist allgemein verständlich"], richtig: 0, erklaerung: "Zusätzlich Symbol oder Text anzeigen." },
  { id: "FIAE-6-11", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "2. Usability", frage: "Was bedeutet **Responsive Design**?", optionen: ["Oberfläche passt sich an Bildschirmgrößen an", "Seite lädt auch bei schwacher Verbindung schnell", "Seite reagiert auf Sprachbefehle", "Seite erfüllt alle Kriterien der Barrierefreiheit"], richtig: 0, erklaerung: "Gleiche Inhalte auf Smartphone, Tablet und PC nutzbar." },
  { id: "FIAE-6-12", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Wie wird eine Anwendung für Menschen **ohne Maus** bedienbar?", optionen: ["Vollständige Tastaturbedienung mit sichtbarem Fokus", "Größere Schaltflächen für Touch-Bedienung", "Zusätzliche Tooltips beim Überfahren mit der Maus", "Automatische Weiterleitung nach jeder Eingabe"], richtig: 0, erklaerung: "Auch für Sprachsteuerung und Hilfsmittel wichtig." },

  // ---------------------------------------------------------------- FIAE-7 Schnittstellen, Web und Architektur
  { id: "FIAE-7-01", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "1. REST-API", frage: "Welche HTTP-Methode entspricht **Read** in CRUD?", optionen: ["GET", "POST", "PUT", "DELETE"], richtig: 0, erklaerung: "Create = POST, Update = PUT/PATCH, Delete = DELETE." },
  { id: "FIAE-7-02", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "1. REST-API", frage: "Was bedeutet, dass eine REST-API **zustandslos** ist?", optionen: ["Jeder Request enthält alle nötigen Informationen", "Der Server speichert den Sitzungszustand je Client", "Die API liefert immer dieselbe Antwort", "Die API funktioniert ohne Netzwerkverbindung"], richtig: 0, erklaerung: "Deshalb sind Aufrufe unabhängig voneinander." },
  { id: "FIAE-7-03", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "1. REST-API", frage: "Welche Methode ist **nicht idempotent**?", optionen: ["POST", "GET", "PUT", "DELETE"], richtig: 0, erklaerung: "Zweimal POST legt zwei Ressourcen an." },
  { id: "FIAE-7-04", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "HTTP-Statuscodes", frage: "Was bedeutet der Statuscode **404**?", optionen: ["Ressource nicht gefunden", "Nicht authentifiziert", "Interner Serverfehler", "Ressource angelegt"], richtig: 0, erklaerung: "4xx = Fehler auf Client-Seite." },
  { id: "FIAE-7-05", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "HTTP-Statuscodes", frage: "Worin unterscheiden sich **401** und **403**?", optionen: ["401 nicht angemeldet, 403 keine Berechtigung", "401 keine Berechtigung, 403 nicht angemeldet", "401 Serverfehler, 403 Clientfehler", "Beide bedeuten „Ressource nicht gefunden“"], richtig: 0, erklaerung: "Unauthorized vs. Forbidden." },
  { id: "FIAE-7-06", modul: "FIAE-7", typ: "zahl", niveau: 1, abschnitt: "HTTP-Statuscodes", frage: "Welcher Statuscode meldet, dass eine Ressource **erfolgreich angelegt** wurde?", richtig: 201, toleranz: 0, erklaerung: "201 Created." },
  { id: "FIAE-7-07", modul: "FIAE-7", typ: "multi", niveau: 2, abschnitt: "Aufbau eines Requests", frage: "Was steht typischerweise im **Header** eines HTTP-Requests?", optionen: ["Content-Type", "Authorization (Token, API-Key)", "Accept", "Die JSON-Nutzdaten", "Cookies"], richtig: [0, 1, 2, 4], erklaerung: "Die Nutzdaten stehen im Body." },
  { id: "FIAE-7-08", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "Aufbau eines Requests", frage: "Was sind in `…/forecast?lat=51.45&lon=7.01&days=3` die Angaben nach dem `?`?", optionen: ["Query-Parameter", "Header", "Body", "Pfadparameter"], richtig: 0, erklaerung: "name=wert, getrennt mit &." },
  { id: "FIAE-7-09", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "2. Datenformate", frage: "Was prüft ein XML-Parser, wenn er die **Wohlgeformtheit** eines Dokuments kontrolliert?", optionen: ["Korrekte Verschachtelung und geschlossene Tags", "Einhaltung der Datentypen aus dem XSD-Schema", "Übereinstimmung mit einer JSON-Vorlage", "Gültigkeit der digitalen Signatur"], richtig: 0, erklaerung: "**Wohlgeformt** = XML-Syntaxregeln eingehalten; **gültig** = zusätzlich schemakonform (XSD/DTD)." },
  { id: "FIAE-7-10", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "3. Architektur", frage: "Was kennzeichnet eine **Microservice-Architektur**?", optionen: ["Kleine, unabhängig deploybare Dienste mit APIs", "Eine große Anwendung mit gemeinsamer Datenbank", "Alle Dienste in einer einzigen Programmiersprache", "Dienste teilen sich einen gemeinsamen Prozess"], richtig: 0, erklaerung: "Skalierbar, aber komplexer zu betreiben." },
  { id: "FIAE-7-11", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "Entwicklungswerkzeuge", frage: "Was unterscheidet einen **Interpreter** von einem Compiler?", optionen: ["Übersetzt den Code bei jeder Ausführung", "Übersetzt einmal vollständig vor der Ausführung", "Erzeugt eine ausführbare Maschinencode-Datei", "Prüft den Code nicht auf Syntaxfehler"], richtig: 0, erklaerung: "Schnelles Testen, aber langsamere Ausführung." },
  { id: "FIAE-7-12", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "Entwicklungswerkzeuge", frage: "Warum ist eine **Versionsverwaltung** bei einem Team von acht Entwicklern unverzichtbar?", optionen: ["Paralleles Arbeiten und Nachvollziehen von Änderungen", "Automatisches Testen jeder Änderung vor dem Speichern", "Schnellere Ausführung des gemeinsamen Codes", "Gesetzliche Pflicht für Softwareprojekte"], richtig: 0, erklaerung: "Konflikte werden erkannt und zusammengeführt." },
  { id: "FIAE-7-13", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "Entwicklungswerkzeuge", frage: "Windows warnt beim Start eines selbst entwickelten Programms vor einem **unbekannten Herausgeber**. Was fehlt?", optionen: ["Code-Signatur mit vertrauenswürdigem Zertifikat", "Ein Installationsprogramm (Setup) für die Software", "Eine Lizenzdatei im Programmverzeichnis", "Ein aktuelles Windows-Sicherheitsupdate"], richtig: 0, erklaerung: "Die Signatur belegt Herkunft und Unverändertheit." },
  { id: "FIAE-7-14", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "4. Netzwerkgrundlagen für Entwickler", frage: "Welches Netzkonzept passt für **Bodensensoren** auf einem großen Feld?", optionen: ["LPWAN (z. B. LoRaWAN)", "SAN", "LAN mit Kupferkabel", "Bluetooth"], richtig: 0, erklaerung: "Hohe Reichweite, geringer Energieverbrauch, kleine Datenmengen." },
  { id: "FIAE-7-15", modul: "FIAE-7", typ: "multi", niveau: 2, abschnitt: "4. Netzwerkgrundlagen für Entwickler", frage: "Welche Merkmale hat **LoRa**?", optionen: ["Reichweite von mehreren Kilometern", "Sehr geringer Energieverbrauch", "Geringe Datenrate", "Gigabit-Übertragung", "Nur im Rechenzentrum nutzbar"], richtig: [0, 1, 2], erklaerung: "Ideal für IoT-Sensoren." },
  { id: "FIAE-7-16", modul: "FIAE-7", typ: "zahl", niveau: 1, abschnitt: "4. Netzwerkgrundlagen für Entwickler", frage: "Wie viele **Byte** hat eine MAC-Adresse?", richtig: 6, toleranz: 0, einheit: "Byte", erklaerung: "Die ersten 3 Byte sind die Herstellerkennung (OUI)." },
  { id: "FIAE-7-17", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "4. Netzwerkgrundlagen für Entwickler", frage: "Welches Feld steht im Ethernet-Frame **direkt nach der Präambel**?", optionen: ["Ziel-MAC-Adresse", "Quell-MAC-Adresse", "Nutzdaten", "Prüfsumme (FCS)"], richtig: 0, erklaerung: "Präambel – Ziel – Quelle – Typ – Daten – FCS." },

  // ---------------------------------------------------------------- FIAE-8 Sicherheit in der Softwareentwicklung
  { id: "FIAE-8-01", modul: "FIAE-8", typ: "mc", niveau: 1, abschnitt: "3. Passwörter sicher speichern", frage: "Wie werden Passwörter in einer Datenbank sicher gespeichert?", optionen: ["Hash mit individuellem Salt (bcrypt/Argon2)", "AES-verschlüsselt mit einem Serverschlüssel", "SHA-256-Hash ohne Salt", "Base64-kodiert im Benutzerdatensatz"], richtig: 0, erklaerung: "Passwörter werden gehasht, nicht verschlüsselt." },
  { id: "FIAE-8-02", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "3. Passwörter sicher speichern", frage: "Welches Problem löst ein **Salt**?", optionen: ["Gleiche Passwörter ergeben verschiedene Hashes", "Das Passwort erreicht die Mindestlänge", "Der Hash lässt sich später wieder umkehren", "Das Passwort wird verschlüsselt übertragen"], richtig: 0, erklaerung: "Das Salt ist nicht geheim und liegt neben dem Hash." },
  { id: "FIAE-8-03", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "3. Passwörter sicher speichern", frage: "Warum sollte man für Passwörter **kein einfaches SHA-256** verwenden?", optionen: ["Zu schnell – Brute Force testet Milliarden/s", "SHA-256 ist mathematisch umkehrbar", "Die Hashes sind für Datenbanken zu lang", "SHA-256 erzeugt häufig Kollisionen"], richtig: 0, erklaerung: "Besser langsame, speicherintensive Verfahren wie bcrypt, scrypt, Argon2." },
  { id: "FIAE-8-04", modul: "FIAE-8", typ: "mc", niveau: 1, abschnitt: "1. Schutzziele", frage: "Sensorwerte sollen **nicht unbemerkt manipuliert** werden können. Welches Schutzziel?", optionen: ["Integrität", "Vertraulichkeit", "Verfügbarkeit", "Anonymität"], richtig: 0, erklaerung: "Umsetzung z. B. mit HMAC oder digitaler Signatur." },
  { id: "FIAE-8-05", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "1. Schutzziele", frage: "Mit welchem Verfahren lässt sich die **Integrität** einer Nachricht prüfen?", optionen: ["HMAC oder digitale Signatur", "Base64-Kodierung der Daten", "Komprimierung mit ZIP", "Symmetrische Verschlüsselung allein"], richtig: 0, erklaerung: "Passt der Prüfwert nicht, wurden die Daten verändert." },
  { id: "FIAE-8-06", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "2. Verschlüsselungsverfahren", frage: "Worauf beruht die Sicherheit von **RSA**?", optionen: ["Faktorisierung großer Primzahlprodukte", "Einem gemeinsamen geheimen Schlüssel", "Der Länge des verwendeten Passworts", "Der Seltenheit von Hashkollisionen"], richtig: 0, erklaerung: "RSA ist asymmetrisch und rechenaufwendig." },
  { id: "FIAE-8-07", modul: "FIAE-8", typ: "mc", niveau: 3, abschnitt: "2. Verschlüsselungsverfahren", frage: "Ist RSA sinnvoll, um **alle Messwerte** eines IoT-Geräts zu verschlüsseln?", optionen: ["Nein – AES für Daten, RSA/ECC nur für Schlüssel", "Ja – RSA ist schneller als AES", "Ja – RSA ist ein symmetrisches Verfahren", "Nein – RSA kann keine Daten verschlüsseln"], richtig: 0, erklaerung: "Das Prinzip der hybriden Verschlüsselung." },
  { id: "FIAE-8-08", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "2. Verschlüsselungsverfahren", frage: "Warum ist die **Transportverschlüsselung bei E-Mail** hybrid?", optionen: ["Kein vorab geteiltes Geheimnis nötig", "Zwei Mailserver sind am Versand beteiligt", "Anhänge werden vor dem Versand komprimiert", "SMTP und IMAP nutzen verschiedene Ports"], richtig: 0, erklaerung: "TLS zwischen Client und Server bzw. zwischen Servern." },
  { id: "FIAE-8-09", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "4. Sichere Programmierung", frage: "Wie verhindert man **SQL-Injection** zuverlässig?", optionen: ["Prepared Statements (parametrisierte Abfragen)", "Längere Tabellennamen", "Eingaben in Großbuchstaben umwandeln", "Mehr Arbeitsspeicher"], richtig: 0, erklaerung: "Eingaben werden als Daten, nicht als SQL-Code behandelt." },
  { id: "FIAE-8-10", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "4. Sichere Programmierung", frage: "Was hilft gegen **Cross-Site Scripting (XSS)**?", optionen: ["Ausgaben kontextgerecht kodieren, CSP setzen", "Prepared Statements für alle Datenbankzugriffe", "Passwörter mit bcrypt hashen", "CSRF-Token in jedes Formular einbauen"], richtig: 0, erklaerung: "XSS schleust Skripte in die Seiten anderer Nutzer ein." },
  { id: "FIAE-8-11", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "4. Sichere Programmierung", frage: "Ein Nutzer ändert in der URL `…/rechnung/1041` auf `1042` und sieht eine fremde Rechnung. Welche Schwachstelle?", optionen: ["Fehlende Zugriffskontrolle", "SQL-Injection über den URL-Parameter", "Cross-Site Scripting (XSS)", "Cross-Site Request Forgery (CSRF)"], richtig: 0, erklaerung: "Die Berechtigung muss serverseitig bei jedem Zugriff geprüft werden." },
  { id: "FIAE-8-12", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "3. Passwörter sicher speichern", frage: "Wie wird ein **Passwort-Reset** sicherer?", optionen: ["Zeitlich begrenzter Einmal-Link plus zweiter Kanal", "Neues Passwort im Klartext per E-Mail senden", "Sicherheitsfrage nach dem Geburtsort", "Reset-Link ohne Ablaufdatum per E-Mail"], richtig: 0, erklaerung: "Ein abgefangener Link allein reicht dann nicht." },
  { id: "FIAE-8-13", modul: "FIAE-8", typ: "mc", niveau: 1, abschnitt: "5. Datenschutz in Anwendungen", frage: "Welche Form der **Einwilligung** ist nach DSGVO gültig?", optionen: ["Aktives Opt-in, freiwillig und widerrufbar", "Vorangekreuztes Kästchen im Formular", "Weitersurfen nach dem Cookie-Hinweis", "Zustimmung in den AGB versteckt"], richtig: 0, erklaerung: "Die Einwilligung muss eindeutig und informiert sein." },
  { id: "FIAE-8-14", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "5. Datenschutz in Anwendungen", frage: "Was bedeutet **Privacy by Default**?", optionen: ["Datenschutzfreundliche Voreinstellungen", "Datenschutz wird nach dem Release ergänzt", "Alle Daten sind standardmäßig öffentlich", "Nutzer müssen Datenschutz selbst aktivieren"], richtig: 0, erklaerung: "Privacy by Design: Datenschutz von Anfang an einplanen." },
  { id: "FIAE-8-15", modul: "FIAE-8", typ: "multi", niveau: 2, abschnitt: "1. Schutzziele", frage: "Welche **Sicherheitsanforderungen** gehören zu einer App mit personenbezogenen Daten?", optionen: ["Sichere Datenübertragung (TLS)", "Sichere Speicherung (Verschlüsselung, Hash für Passwörter)", "Sichere Authentifizierung (MFA)", "Sitzungsende bei Inaktivität", "Debugmeldungen für alle Nutzer anzeigen"], richtig: [0, 1, 2, 3], erklaerung: "Fehlerdetails gehören nicht in die Oberfläche." },

  // ---------------------------------------------------------------- Ergänzungen FIAE-1 bis FIAE-8
  { id: "FIAE-1-20", modul: "FIAE-1", typ: "zahl", niveau: 2, abschnitt: "Netzplan", frage: "Vorgang D hat FAZ 9 und SAZ 11. Wie groß ist sein **Gesamtpuffer** in Tagen?", richtig: 2, toleranz: 0, erklaerung: "GP = SAZ − FAZ = 11 − 9." },
  { id: "FIAE-2-17", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "„Rad ausleihen“ enthält **immer** „Rad entsperren“. Welche Beziehung passt?", optionen: ["«include» von Ausleihen zu Entsperren", "«extend» von Entsperren zu Ausleihen", "Generalisierung", "Assoziation zum Akteur"], richtig: 0, erklaerung: "include = Pflichtbestandteil, der Pfeil zeigt zum eingebundenen Fall." },
  { id: "FIAE-2-18", modul: "FIAE-2", typ: "mc", niveau: 2, abschnitt: "3. Use-Case-Diagramm", frage: "Wohin zeigt der Pfeil einer **«extend»**-Beziehung?", optionen: ["Vom erweiternden Fall zum Basisfall", "Vom Basisfall zum erweiternden Fall", "Zum Akteur", "Es gibt keinen Pfeil"], richtig: 0, erklaerung: "Der optionale Fall erweitert den Basisfall unter einer Bedingung." },
  { id: "FIAE-2-19", modul: "FIAE-2", typ: "mc", niveau: 1, abschnitt: "User Stories", frage: "Welches Merkmal gehört zu den **INVEST**-Kriterien einer guten User Story?", optionen: ["Testbar – es gibt prüfbare Akzeptanzkriterien", "Technisch – sie beschreibt die Implementierung", "Terminiert – sie nennt ein festes Lieferdatum", "Teamgebunden – nur eine Person bearbeitet sie"], richtig: 0, erklaerung: "INVEST: **I**ndependent, **N**egotiable, **V**aluable, **E**stimable, **S**mall, **T**estable." },
  { id: "FIAE-2-20", modul: "FIAE-2", typ: "multi", niveau: 2, abschnitt: "Anwendungsfallbeschreibung", frage: "Was gehört in eine **Anwendungsfallbeschreibung**?", optionen: ["Vorbedingung", "Ablauf (Standardszenario)", "Alternative Abläufe", "Nachbedingung", "Klassendiagramm"], richtig: [0, 1, 2, 3], erklaerung: "Dazu Name, Akteure und Auslöser." },
  { id: "FIAE-3-15", modul: "FIAE-3", typ: "mc", niveau: 1, abschnitt: "1. Aktivitätsdiagramm", frage: "Was bedeutet ein **Gabelungsbalken (Fork)** im Aktivitätsdiagramm?", optionen: ["Ab hier laufen mehrere Abläufe parallel", "Hier wird eine Bedingung geprüft", "Hier endet die Aktivität", "Hier wird ein Objekt erzeugt"], richtig: 0, erklaerung: "Der Join-Balken führt die parallelen Abläufe wieder zusammen." },
  { id: "FIAE-3-16", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "1. Aktivitätsdiagramm", frage: "Wie verhält sich ein **Vereinigungsbalken (Join)**?", optionen: ["Er wartet, bis alle eingehenden Abläufe angekommen sind", "Er lässt den ersten ankommenden Ablauf durch", "Er wählt zufällig einen Ablauf", "Er beendet alle Abläufe"], richtig: 0, erklaerung: "Das Zusammenführen einer Entscheidung (Merge) wartet dagegen nicht." },
  { id: "FIAE-3-17", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Woran erkennen Sie eine **synchrone** Nachricht im Sequenzdiagramm?", optionen: ["Gefüllte Pfeilspitze, Sender wartet", "Offene Pfeilspitze, Sender wartet nicht", "Gestrichelte Linie mit offener Spitze", "Durchgezogene Linie ohne Pfeilspitze"], richtig: 0, erklaerung: "Asynchron: offene Spitze; Antwort: gestrichelt." },
  { id: "FIAE-3-18", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "2. Sequenzdiagramm", frage: "Welches Fragment stellt **„entweder – oder“** dar?", optionen: ["alt", "opt", "loop", "par"], richtig: 0, erklaerung: "opt = optional, loop = Wiederholung, par = parallel." },
  { id: "FIAE-3-19", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "3. Zustandsdiagramm", frage: "Was beschreibt `entry / tür schließen` in einem Zustand des Zustandsdiagramms?", optionen: ["Eine Aktion beim Betreten des Zustands", "Eine Aktion beim Verlassen des Zustands", "Eine Aktivität, solange der Zustand gilt", "Die Bedingung für einen Übergang"], richtig: 0, erklaerung: "**entry** = beim Eintritt, **exit** = beim Verlassen, **do** = solange das Objekt im Zustand ist." },
  { id: "FIAE-3-20", modul: "FIAE-3", typ: "mc", niveau: 2, abschnitt: "3. Zustandsdiagramm", frage: "Was beschreibt `do / fahren` in einem Zustand?", optionen: ["Aktivität, solange das Objekt im Zustand ist", "Aktion beim Betreten des Zustands", "Aktion beim Verlassen des Zustands", "Ereignis, das einen Übergang auslöst"], richtig: 0, erklaerung: "entry beim Betreten, exit beim Verlassen." },
  { id: "FIAE-4-18", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Der Tarif (Minuten-, Tages-, Abotarif) soll zur Laufzeit austauschbar sein. Welches Muster?", optionen: ["Strategy", "Singleton", "Adapter", "Observer"], richtig: 0, erklaerung: "Austauschbare Algorithmen hinter einer gemeinsamen Schnittstelle." },
  { id: "FIAE-4-19", modul: "FIAE-4", typ: "mc", niveau: 2, abschnitt: "3. Entwurfsmuster", frage: "Eine vorhandene Bibliothek hat eine andere Schnittstelle als erwartet. Welches Muster?", optionen: ["Adapter", "Factory Method", "Strategy", "MVC"], richtig: 0, erklaerung: "Der Adapter übersetzt zwischen den Schnittstellen (Strukturmuster)." },
  { id: "FIAE-4-20", modul: "FIAE-4", typ: "mc", niveau: 1, abschnitt: "1. Klassendiagramm", frage: "Was bedeutet die Multiplizität **0..1**?", optionen: ["Keins oder genau eins", "Genau eins", "Mindestens eins", "Beliebig viele"], richtig: 0, erklaerung: "`*` = beliebig viele, `1..*` = mindestens eins." },
  { id: "FIAE-5-15", modul: "FIAE-5", typ: "mc", niveau: 1, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Die Tabelle `Bestellposition(BestellNr, ArtikelNr, Menge, Artikelbezeichnung)` hat den Schlüssel (BestellNr, ArtikelNr). Welche Normalform ist verletzt?", optionen: ["2. NF – Bezeichnung hängt nur von ArtikelNr ab", "1. NF – die Menge ist kein atomarer Wert", "3. NF – die Menge hängt von der Bezeichnung ab", "Keine – die Tabelle ist vollständig normalisiert"], richtig: 0, erklaerung: "Eine **partielle Abhängigkeit** von einem Teil des zusammengesetzten Schlüssels verletzt die 2. NF → Artikel in eine eigene Tabelle auslagern." },
  { id: "FIAE-5-16", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Eine Tabelle hat den Schlüssel (BestellNr, ArtikelNr); die Artikelbezeichnung hängt nur von ArtikelNr ab. Welche Normalform ist verletzt?", optionen: ["2. Normalform", "1. Normalform", "3. Normalform", "Boyce-Codd-Normalform, aber nicht 3. NF"], richtig: 0, erklaerung: "Teilabhängigkeit vom zusammengesetzten Schlüssel." },
  { id: "FIAE-5-17", modul: "FIAE-5", typ: "mc", niveau: 2, abschnitt: "2. Redundanz, Anomalien, Normalisierung", frage: "Wodurch entsteht eine **Löschanomalie**?", optionen: ["Mit einem Datensatz gehen andere Informationen verloren", "Ein Fremdschlüssel verhindert das Löschen eines Satzes", "Gelöschte Datensätze bleiben im Transaktionslog erhalten", "Beim Löschen werden die Indizes nicht aktualisiert"], richtig: 0, erklaerung: "Beispiel: Stehen Kunde und Auftrag in einer Tabelle, verschwinden beim Löschen des einzigen Auftrags auch die Kundendaten." },
  { id: "FIAE-5-18", modul: "FIAE-5", typ: "mc", niveau: 1, abschnitt: "ER-Modell in Tabellen überführen", frage: "Wie wird eine **m:n-Beziehung** umgesetzt?", optionen: ["Zwischentabelle mit beiden Fremdschlüsseln", "Fremdschlüssel auf der m-Seite", "Gemeinsame Tabelle für beide Entitäten", "Fremdschlüssel in beiden Tabellen"], richtig: 0, erklaerung: "Die beiden Fremdschlüssel bilden oft den Primärschlüssel." },
  { id: "FIAE-5-19", modul: "FIAE-5", typ: "zahl", niveau: 2, abschnitt: "Speicherbedarf abschätzen", frage: "2 000 Räder senden alle 30 s einen Datensatz mit 64 Byte. Wie viele **MB** (dezimal) entstehen pro Tag?", richtig: 368.64, toleranz: 0.01, erklaerung: "86 400 ÷ 30 = 2 880 Datensätze je Rad · 2 000 · 64 B = 368 640 000 B = 368,64 MB." },
  { id: "FIAE-5-20", modul: "FIAE-5", typ: "multi", niveau: 2, abschnitt: "4. NoSQL und große Datenmengen", frage: "Welche Arten von **NoSQL-Datenbanken** gibt es?", optionen: ["Key-Value-Speicher", "Dokumentenorientiert", "Spaltenorientiert", "Graphdatenbank", "Relationale Datenbank"], richtig: [0, 1, 2, 3], erklaerung: "Relational ist gerade nicht NoSQL." },
  { id: "FIAE-6-13", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "Steuerelemente passend wählen", frage: "Nutzer sollen **genau eine** von drei Zahlungsarten wählen. Welches Steuerelement?", optionen: ["Radiobuttons", "Checkboxen", "Mehrzeiliges Textfeld", "Schieberegler"], richtig: 0, erklaerung: "Checkboxen erlauben Mehrfachauswahl." },
  { id: "FIAE-6-14", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "Steuerelemente passend wählen", frage: "Aus 80 Stationen soll eine gewählt werden, der Platz ist knapp. Welches Element passt am besten?", optionen: ["Dropdown mit Suchfunktion", "80 Radiobuttons", "80 Checkboxen", "Freitextfeld ohne Prüfung"], richtig: 0, erklaerung: "Spart Platz und verhindert Tippfehler." },
  { id: "FIAE-6-15", modul: "FIAE-6", typ: "multi", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Welche Maßnahmen verbessern die **Barrierefreiheit** eines Webformulars? (mehrere richtig)", optionen: ["Jedes Eingabefeld hat ein zugeordnetes Label", "Fehlermeldungen nennen Feld und Lösung im Text", "Pflichtfelder sind nur durch rote Farbe markiert", "Die Tab-Reihenfolge folgt der sichtbaren Anordnung", "Hinweise erscheinen nur beim Überfahren mit der Maus"], richtig: [0, 1, 3], erklaerung: "Farbe als einziges Merkmal und reine Maus-Hinweise schließen Nutzer aus (WCAG 1.4.1 und 2.1.1)." },
  { id: "FIAE-6-16", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "3. Barrierefreiheit", frage: "Welches Kontrastverhältnis fordert WCAG (Stufe AA) für normalen Text mindestens?", optionen: ["4,5 : 1", "2 : 1", "10 : 1", "1 : 1"], richtig: 0, erklaerung: "Für großen Text reichen 3 : 1." },
  { id: "FIAE-6-17", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "3. Barrierefreiheit", frage: "Welches Gesetz verpflichtet seit Juni 2025 viele Anbieter digitaler Dienstleistungen zur Barrierefreiheit?", optionen: ["Barrierefreiheitsstärkungsgesetz", "Bundesdatenschutzgesetz", "Telekommunikationsgesetz", "Onlinezugangsgesetz"], richtig: 0, erklaerung: "Es setzt den European Accessibility Act um." },
  { id: "FIAE-6-18", modul: "FIAE-6", typ: "mc", niveau: 1, abschnitt: "1. Vom Skizzieren zum Prototyp", frage: "Wozu dient ein **klickbarer Prototyp** im Usability-Test?", optionen: ["Nutzer testen Abläufe, bevor programmiert wird", "Er ersetzt die spätere Implementierung vollständig", "Er dient als Vorlage für das Datenbankschema", "Er prüft die Serverlast unter vielen Nutzern"], richtig: 0, erklaerung: "Frühes Feedback ist günstig: Fehler im Bedienablauf werden gefunden, bevor Code entsteht." },
  { id: "FIAE-6-19", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "Usability testen", frage: "Testpersonen sprechen beim Bedienen laut aus, was sie denken. Wie heißt die Methode?", optionen: ["Thinking Aloud", "A/B-Test", "Lasttest", "Code-Review"], richtig: 0, erklaerung: "Zeigt, wo Nutzer die Oberfläche anders verstehen als geplant." },
  { id: "FIAE-6-20", modul: "FIAE-6", typ: "mc", niveau: 2, abschnitt: "2. Usability", frage: "Der Speichern-Button steht in jeder Maske an einer anderen Stelle. Welcher Grundsatz der ISO 9241-110 ist verletzt?", optionen: ["Erwartungskonformität", "Steuerbarkeit", "Robustheit gegen Benutzungsfehler", "Aufgabenangemessenheit"], richtig: 0, erklaerung: "Einheitliche, gewohnte Anordnung erfüllt die Erwartungen der Nutzer." },
  { id: "FIAE-7-18", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "1. REST-API", frage: "Welche HTTP-Methode ändert eine Ressource **teilweise**?", optionen: ["PATCH", "PUT", "POST", "HEAD"], richtig: 0, erklaerung: "**PUT** ersetzt die Ressource vollständig, **PATCH** ändert einzelne Felder." },
  { id: "FIAE-7-19", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "HTTP-Statuscodes", frage: "Ein Client ruft einen Endpunkt in kurzer Zeit zu oft auf. Welcher Statuscode passt?", optionen: ["429 Too Many Requests", "503 Service Unavailable", "400 Bad Request", "409 Conflict"], richtig: 0, erklaerung: "**429** signalisiert Rate Limiting, häufig mit einem Retry-After-Header." },
  { id: "FIAE-7-20", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "2. Datenformate", frage: "Was prüft eine **XSD**?", optionen: ["Einhaltung von Struktur und Datentypen (Gültigkeit)", "Nur die Wohlgeformtheit des XML-Dokuments", "Korrekte Syntax eines JSON-Dokuments", "Integrität über eine digitale Signatur"], richtig: 0, erklaerung: "Gültig = wohlgeformt und schemakonform." },
  { id: "FIAE-8-16", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "4. Sichere Programmierung", frage: "Wie schützt man ein Formular gegen **CSRF**?", optionen: ["Sitzungsgebundenes Token und SameSite-Cookies", "Prepared Statements für alle Abfragen", "Längere Mindestlänge für Passwörter", "Base64-Kodierung der Formularfelder"], richtig: 0, erklaerung: "Eine fremde Seite kennt das Token nicht." },
  { id: "FIAE-8-17", modul: "FIAE-8", typ: "mc", niveau: 3, abschnitt: "3. Passwörter sicher speichern", frage: "Was ist ein **Pepper**?", optionen: ["Geheimer Zusatzwert außerhalb der Datenbank", "Zufälliger Salt pro Benutzerkonto", "Symmetrisches Verschlüsselungsverfahren", "Hashalgorithmus mit Arbeitsfaktor"], richtig: 0, erklaerung: "Schützt zusätzlich, wenn nur die Datenbank gestohlen wird." },
  { id: "FIAE-8-18", modul: "FIAE-8", typ: "mc", niveau: 1, abschnitt: "5. Datenschutz in Anwendungen", frage: "Was bedeutet **Datenminimierung**?", optionen: ["Nur für den Zweck nötige Daten verarbeiten", "Daten vor der Speicherung komprimieren", "Daten löschen, wenn der Speicher voll ist", "Daten anonymisiert unbegrenzt sammeln"], richtig: 0, erklaerung: "Grundsatz nach Art. 5 DSGVO." },
  { id: "FIAE-8-19", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "4. Sichere Programmierung", frage: "Wozu dient **Code-Signing**?", optionen: ["Herkunft und Unverändertheit prüfbar machen", "Die Ausführung des Programms beschleunigen", "Den Quelltext vor Einsicht verschlüsseln", "Die Softwarelizenz beim Start prüfen"], richtig: 0, erklaerung: "Signatur mit dem privaten Schlüssel des Herstellers." },
  { id: "FIAE-8-20", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "1. Schutzziele", frage: "Ein Befehl an das Fahrradschloss muss **nachweislich vom Backend** stammen. Welches Schutzziel?", optionen: ["Authentizität", "Verfügbarkeit", "Vertraulichkeit", "Anonymität"], richtig: 0, erklaerung: "Umsetzung mit digitaler Signatur oder HMAC." },
  // Ergänzungen Prüfungskatalog: cyber-physische Systeme, Betrieb, Kerberos
  { id: "FIAE-7-21", modul: "FIAE-7", typ: "mc", niveau: 1, abschnitt: "5. Cyber-physische Systeme", frage: "Welche Komponente eines cyber-physischen Systems öffnet auf einen Befehl hin ein **Ventil**?", optionen: ["Aktor", "Sensor", "Gateway", "Datenbank"], richtig: 0, erklaerung: "Sensoren messen, Aktoren wirken auf die physische Welt ein." },
  { id: "FIAE-7-22", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "6. Betrieb", frage: "Was ist das vorrangige Ziel des **Incident-Managements**?", optionen: ["den Normalbetrieb so schnell wie möglich wiederherstellen", "die Ursache wiederkehrender Störungen dauerhaft beseitigen", "neue Funktionen planen und priorisieren", "Lizenzen für den Betrieb beschaffen"], richtig: 0, erklaerung: "Die dauerhafte Ursachenbeseitigung ist Aufgabe des Problem-Managements." },
  { id: "FIAE-7-23", modul: "FIAE-7", typ: "mc", niveau: 2, abschnitt: "6. Betrieb", frage: "Welchen Vorteil bietet ein **Ticketsystem** im Support?", optionen: ["Jede Störung wird mit Priorität, Zuständigkeit und Verlauf nachvollziehbar erfasst", "Störungen beheben sich automatisch", "Es ersetzt das Monitoring der Server", "Es verhindert, dass Störungen auftreten"], richtig: 0, erklaerung: "Außerdem werden Bearbeitungszeiten messbar und Lösungen dokumentiert." },
  { id: "FIAE-8-21", modul: "FIAE-8", typ: "mc", niveau: 2, abschnitt: "3. Passwörter sicher speichern", frage: "Wie funktioniert die Anmeldung mit **Kerberos**?", optionen: ["Ein Key Distribution Center stellt zeitlich begrenzte Tickets aus, mit denen der Client Dienste ohne erneute Passworteingabe nutzt", "Das Passwort wird bei jedem Dienstaufruf im Klartext übertragen", "Jeder Dienst speichert eine eigene Kopie aller Passwörter", "Die Anmeldung erfolgt ausschließlich über Fingerabdruck"], richtig: 0, erklaerung: "Single Sign-on im Active Directory; die Uhren müssen synchron sein." },
]
